INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (8443, '把 3 枚阿拉希盆地荣誉徽记带给战场外的部落战争使者。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Bring 3 Arathi Basin Mark of Honor to a Horde Warbringer outside the battlegrounds.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (8608, '把 20 卷魔纹绷带带给奥格瑞玛精神谷的卡隆女士。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Bring 20 Mageweave Bandages to Lady Callow at the Valley of Spirits in Orgrimmar.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (39980, '击杀过去一天内不义击杀数最多的玩家。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Kill the player with the most dishonorable kills during the past day.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41274, '从艾泽拉斯各地收集爱情信物，带给奎·Q·皮德菲特。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Retrieve mementos of love from all around Azeroth and bring them to Kwee Q. Peddlefeet.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41277, '前往荒芜之地的科尔桑废墟寻找瑟格伦。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Travel to the Ruins of Corthan in the Badlands and search for Thegren.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41278, '前往荒芜之地的科尔桑废墟寻找瑟格伦。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Travel to the Ruins of Corthan in the Badlands and search for Thegren.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41280, '完成瑟格伦的手艺考核，然后把作品呈给他。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Complete Thegrens test of craftsmanship and present him with your work afterwards.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41285, '带着冒险者的项链回到铁炉堡的塔瓦斯德·基瑟尔处。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Return with the adventurers necklace to Talvash del Kissel in Ironforge.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41293, '把你和他人设计的珠宝呈给巧匠。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Present The Artificer with jewelry from your own and someone elses design.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41298, '把马托加之首带给诅咒之地的收藏家库米沙。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Bring the Head of Matogar to Kumisha the Collector in the Blasted Lands.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41300, '去和那些威胁铁炉堡塔瓦斯德·基瑟尔的可疑家伙谈谈。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Talk to the suspicious folk threatening Talvash del Kissel in Ironforge.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41301, '回到铁炉堡秘法区的塔瓦斯德·基瑟尔处，付给他报酬。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Return to Talvash del Kissel in the Mystic Ward of Ironforge and give him his payment.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41303, '前往贫瘠之地的棘齿城，四处打听格里兹比和他货物的下落。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Travel to Ratchet in the Barrens and ask around for Grizzbys and his cargos whereabouts.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41304, '寻找格里兹比，然后回到斯帕克沃特港的塔克纳兹·铜火处。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Look for Grizzby and return to Tacknazz Copperfire in Sparkwater Port afterwards.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41305, '塔克纳兹需要一条金项链和血色修道院的一颗巨型红宝石。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Tacknazz needs a golden necklace and a giant ruby from the Scarlet Monastery.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41309, '带着扎拉什吉的宝石油回到热砂港的凡兹·斯帕克斯普林处。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Return with Zalashjis Gemstone Oil to Fanzy Sparkspring in Steamwheedle Port.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41313, '为艾萨拉塔中的大法师克希雷姆收集地脉水晶。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Collect the ley line crystals for Archmage Xylem at his tower in Azshara.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41321, '为艾萨拉的阿克扎多尔带 3 个海妖之脑，供他“恢复心智”。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Bring Akh Zador in Azshara three Siren Brains for his ‘mental recovery.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41323, '带着阿克扎多尔的裂隙行者手杖和贾玛兰的魔精回到艾萨拉的阿克扎多尔处。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Return with Akh Zadors Riftwalker Cane and the Mojo of Jammalan to Akh Zador in Azshara.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41336, '为凄凉之地的巧匠从通灵学院取回一枚替代符文。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Collect a substitute rune from the Scholomance for The Artificer in Desolace.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41342, '在海加尔山先知之丘净化消散的幽魂，然后回到守护者雷姆洛斯处。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Cleanse the Dissipating Spectre at the Prophets Hill in Hyjal and return to Keeper Remulos.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41354, '为阿尔多雷尔解救凯尔瑟利尔受苦与悲恸的上层精灵亡魂。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Free the spirits of Suffering and Anguished Highborne within KelTheril for AlDorel.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41358, '前往冬泉谷玛兹索瑞尔山顶，就阿尔多雷尔揭示的真相与哈蕾交谈。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Speak to Haleh at the top of Mazthoril about the truth revealed by AlDorel in Winterspring.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41368, '杀死军械库军需官达格尔姆，把巴兹尔的日志带回幽暗城交给他。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Slay Armory Quartermaster Daghelm and return Basils journal to him in Undercity.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41374, '在卡拉赞墓穴杀死贪婪的斯特里戈伊，然后回到卡拉赞下层大厅的厨师处。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Slay the Ravenous Strigoi in Karazhan Crypts and return to The Cook in Lower Karazhan Halls.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41379, '把纯净的狼人之血带给海加尔山诺达纳尔的大德鲁伊梦风。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Bring Pure Worgen Blood to Arch Druid Dreamwind at Nordanaar in Hyjal.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41384, '杀死守护者怒月。他就在卡拉赞上层大厅。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Slay Keeper Gnarlmoon. He can be found in the Upper Chambers of Karazhan.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41385, '前往吉尔尼斯城，探查第二个普里科利希的下落。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Venture to Gilneas City and search for the whereabouts of the second Pricolich.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41391, '从地精手中夺回贵重文件，带给暴风城的刺客伦兹克。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Recover valuable documents from the goblin and bring them to Renzik the Shiv in Stormwind.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41392, '潜入西部荒野的死亡矿井，取得沃斯的沸腾药酒。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Infiltrate the Deadmines in Westfall and acquire Voss Sizzling Brew.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41393, '把罗尔加斯特的灼热之眼带给弗雷岛的马赛厄斯·明心。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Bring the Searing Eye of Rholgast to Mathias Brightheart on Fray Island.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41399, '用你手上的物品，换取最合乎你需求的那一件。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Trade in your current item for the item that best suits your needs.
