INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41520, '为贫瘠之地弗雷岛的马赛厄斯·明心取回陈氏法杖。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Recover the Staff of Chen for Mathias Brightheart on Fray Island in the Barrens.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41529, '把威利家族的弩送给弗雷岛的马赛厄斯·明心。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Present Mathias Brightheart on Fray Island with a Willey family crossbow.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41532, '取得上层精灵之弓，献给贫瘠之地弗雷岛的马赛厄斯·明心。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Acquire the Highborne bow and offer it to Mathias Brightheart on Fray Island in the Barrens.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41544, '取得一罐泥土，献给贫瘠之地弗雷岛的马赛厄斯·明心。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Acquire the Jar of Dirt and offer it to Mathias Brightheart on Fray Island in the Barrens.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41547, '把艾斯卡达尔之枝交还给弗雷岛的马赛厄斯·明心。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Return the Branch of Eskhandar to Mathias Brightheart, on Fray Island.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41550, '把一袋手术刀送给贫瘠之地弗雷岛的马赛厄斯·明心。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Deliver the Pouch of Surgical Daggers to Mathias Brightheart on Fray Island in the Barrens.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41551, '若想重新学习金饰加工，再去凄凉之地找巧匠。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Should you wish to relearn Goldsmithing, speak with The Artificer in Desolace once more.
