INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41637, '与安伯郡教堂的孩子们交谈，纠正他们对巴洛的认识。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Talk with the children at Ambershire Church and revise their knowledge about Balor.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41639, '把女巫的原料送到北风北部她的家中。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Bring the Witch of Northwind her ingredients to her house in northern Northwind.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41640, '把杜尔米尔的遗物还给丹莫罗南门要塞的他本人。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Return Durmirs Belongings to him at the South Gate Garrison in Dun Morogh.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41643, '盘问安伯郡的镇民。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Interrogate the townsfolk of Ambershire.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41644, '找到北风的迪菲亚总部，搜寻有关绑架的线索。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Locate the Defias headquarters in Northwind and search for clues about the abductions.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41649, '听查波·查皮布拉斯的录音。录音盒就在永望镇他身旁。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Listen to Zappo Zapblasts recording. The recording box stands next to him in Everlook.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41650, '找出永望镇广播劫持者。查波建议去艾萨拉东北部搜寻。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Find the Everlook Broadcast hijacker. Zappo suggests searching northeastern Azshara.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41664, '搜查黑暗骑士的帐篷，带着发现回去见舍伍德公爵。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Search the Dark Knights tent and return to Duke Sherwood with your findings.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41666, '为琥珀釉甜甜圈收集所需的原料，然后回到米切尔处。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Gather the required ingredients for Amberglaze Donuts and return to Mitchell.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41670, '从鬃须洞穴取回 20 支蜡烛，交给园丁克莱夫。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Retrieve 20 candles from the Bristlewhisker Cavern and return them to Groundskeeper Clive.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41673, '进入岸边洞穴杀死格布尔加，把她的珍珠交给码头旁的亨利。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Enter the cave by the shore and slay Grrblga, return her pearl to Henry by the dock.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41678, '为审判官阿巴顿从旧修道院取回圣光之杯。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Retrieve the Chalice of Light from the old Abbey for Inquisitor Abbadon.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41679, '为北风修道院墓穴的特里斯顿·兰卡斯特收集焦黑的骸骨。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Collect Charred Bones for Triston Lancaster at the abbey crypt in Northwind.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41682, '破坏 15 桶黑铁火药，然后回到北风北部的杜尔·狼嗥处。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Sabotage fifteen Dark Iron Gunpowder Kegs and return to Dul Wolfsnarl in northern Northwind.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41685, '把霍桑的日志交给暴风城旧城区的马迪亚斯·肖尔大师。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Deliver Hawthornes Journal to Master Mathias Shaw in Stormwinds Old Town.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41688, '把被偷的马料还给北风米登霍尔马场的马夫格林特。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Return the stolen horse feed to Horsekeeper Geringt at Mildenhall Horse Farm in Northwind.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41690, '在北风寻找能帮你救治受伤鸭子的人。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Search Northwind for someone able to assist you with the injured duck.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41691, '为女巫集舍中的北风女巫在她家中收集所需的原料。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Gather the needed ingredients for the Witch of Northwind at her house in the Witch Coven.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41692, '在巴洛微风港废墟附近的高地与军情七处部队会合。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Convene with the SI:7 corps on the plateau near the Ruins of Breezehaven on Balor.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41696, '为巴洛军情七处哨站的诺普西·刺距取得风暴掠夺者的手稿。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Acquire Stormreaver Writings for Noppsy Spickerspan at the SI:7 Outpost on Balor.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41698, '在巴洛安放炸药后，回到军情七处哨站的鲁夫斯·锤击处。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Return to Rufus Hammerstrike at the SI:7 Outpost after placing the explosives on Balor.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41700, '找到舵手维里克斯，把尤妮克的罗盘带回巴洛以北岛上的她手中。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Find Helmsman Verix and return Yunies Compass to her on the island north of Balor.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41704, '净化格雷汉领主的仆从，然后回到巴洛西部他庄园中的他那里。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Cleanse Lord Grahans servants and return to him in his estate on western Balor.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41707, '金里尔需要强效孢子来配制血清。她在巴洛的军情七处哨站等候。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Kinrial requires potent spores for her serum. She waits in the SI:7 Outpost on Balor.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41710, '带着所需的材料回到巴洛军情七处哨站的水法师芬尼根处。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Return with the needed reagents to Hydromancer Finnigan in the SI:7 Outpost on Balor.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41711, '安抚那颗珍珠，然后回到巴洛军情七处哨站的水法师芬尼根处。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Calm the pearl and return to Hydromancer Finnigan in the SI:7 Outpost on Balor afterwards.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41718, '把指令带给阴森之地裂刃哨站的指挥官阿格纳什。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Bring the orders to Commander Aggnash at Shatterblade Post in Grim Reaches.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41724, '为阴森之地裂刃哨站的加尔盖克在盖斯卡尔杀死雷斯卡格·沼牙。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Slay Rethkag Mirefang at Gethkar for Gargekk at Shatterblade Post in Grim Reaches.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41727, '为阴森之地裂刃哨站的先知莫桑收集 5 瓶入迷之血。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Gather 5 Vials of Entranced Blood for Far Seer Mothang at Shatterblade Post in Grim Reaches.
