INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41735, '为阴森之地裂刃哨站的巴戈纳克收集 8 块石皮肋肉。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Gather 8 Stonehide Flanks for Bargolnakk at Shatterblade Post in Grim Reaches.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41747, '把一批卷轴送到艾尔文森林阿祖拉之塔的安东纳斯·裂隙凝视。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Deliver the Shipment of Scrolls to Antonas Riftgaze at the Tower of Azora in Elwynn Forest.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41754, '把红印石板带给铁炉堡图书馆的某位史学家。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Bring the Redbrand Tablet to one of the historians at The Library in Ironforge.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41755, '把红印石板带给铁炉堡秘法区的托尔温·红印。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Bring the Redbrand Tablet to Torwyn Redbrand in the Mystic Ward of Ironforge.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41757, '把霸主黑心的首级带给米奈希尔港的斯托特菲斯特船长。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Bring Captain Stoutfist in Menethil Harbor the head of Overlord Blackheart.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41768, '把北风的报告交给暴风城要塞的卡特拉娜·普瑞斯托女士。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Deliver the reports of Northwind to Lady Katrana Prestor in Stormwind Keep.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41783, '为巴洛军情七处哨站的诺普西·刺距取回文件。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Acquire the documents for Noppsy Spickerspan in the SI:7 Outpost on Balor.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41793, '前往阴森之地的裂刃哨站，与他们的指挥官交谈。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Travel to Shatterblade Post in the Grim Reaches and speak to their commander.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41797, '把阿维特·费尔伍德的信带给北风安伯伍德堡的芭芭拉·李。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Bring Avette Fellwoods Letter to Barbara Lee at Amberwood Keep in Northwind.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41798, '罗纳德·基里安要你去巴洛协助他妻子的工作。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Ronald Gillian asked you to join his wife on Balor to assist in her work.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41801, '在阴森谷的大橡树附近找到一头蓝色龙裔。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Find a Blue Dragonkin in the vicinity of a great oak in the Grim Hollow.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41809, '用龙火炸弹削弱斯卡丁的护盾，然后击败斯卡丁巫师。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Use the Dragonfire Bomb to weaken Skardyns shield, then defeat the Skardyn sorcerer.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41813, '在范德农庄找到那箱月光酒，交还给奥尔米尔·半角。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Find the crate of moonshine at Vander Farmstead and return it to Olmir Halfhorn.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41821, '杀死无辜者残骸，然后回到破风角的奥金处。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Slay Remains of the Innocent and return to Ojin in Stormbreaker Point.
