INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41825, '把米塞拉科斯之核带给雷霆崖长者高地的玛加萨·野性图腾。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Bring the Core of Mycellakos to Magatha Grimtotem in The Elder Rise, Thunder Bluff.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41828, '杀死 7 名军情七处斥候，然后回到破风角的基尔罗格·死眼处。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Slay 7 SI:7 Scouts and return to Kilrogg Deadeye in Stormbreaker Point.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41829, '收集 30 只风暴掠夺者术士之眼，然后回到破风角的基尔罗格·死眼处。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Collect 30 Stormreaver Warlock Eye and return to Kilrogg Deadeye in Stormbreaker Point.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41836, '杀死哈雷丽丝女士，把她的灵魂和她携带的物品带回去交给小屋中的德拉克斯尔。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Slay Lady Harelyss, return her soul and the item she carries to Drakthul in his hut.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41846, '向阴森之地顿基萨斯的法官胡尔丹·硬手报到。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Report to Magistrate Hurdam Toughhand in Dun Kithas in Grim Reaches.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41848, '在阴森之地的丘陵中找到通往格瑞姆巴托的遗忘通道。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Find a forgotten passage to Grim Batol in the hills of Grim Reaches.
