INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41850, '为勘察员尘肩从萨尔加拉兹矿场取回纳拉兹宝石。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Recover the Gemstone of Naraz from SalGalaz Mines for Prospector Dustshoulder.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41858, '杀死 8 只沼鳃鱼人、8 只沼鳃泥居者和它们的首领——屠夫加吉尔。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Slay 8 Miregill Murlocs, 8 Miregill Muckdwellers and their leader - Gargill the Butcher.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41859, '在北风寻找神秘埃德林的线索，完成他最后的遗愿。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Search for clues about the enigmatic Edrin in Northwind and fulfill his final wish.
