INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41867, '从腐化的软泥怪身上收集 5 份暗影诅咒样本，带给多萨斯·里德。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Collect 5 Shadow-Cursed Samples from corrupted oozes and bring them to Dorthas Read.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41869, '为顿基萨斯的哈菲格·铁眉杀死 8 只格里姆斯凯尔迅猛龙和 8 只格里姆斯凯尔尖啸者。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Slay 8 Grimscale Raptors and 8 Grimscale Screechers for Harfig Irombrow in Dun Kithas.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41871, '向顿基萨斯治安官大楼的法官胡尔丹·硬手报到。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Report to Magistrate Hurdam Toughhand in the Magistrate building in Dun Kithas.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41879, '为板须熔炉的格鲁克森·板须找到一块风暴铸造水晶。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Find a Stormwrought Crystal for Grukson Slatebeard at Slatebeards Forge.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41880, '在扎姆盖斯要塞杀死 10 名龙喉精英和 10 名龙喉勇士。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Slay 10 Dragonmaw Elite and 10 Dragonmaw Champions in Zarmgeth Stronghold.
