INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41904, '为艾萨拉的格拉兹诺带 1 份木喉树液和 1 份亡灵精华。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Bring 1 Timbermaw Sap, and 1 Essence of Undeath for Grathnol in Azshara.
