INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41919, '把月丝谷的丝线卷带给摩洛盖村的长者贤者阿佐卡尔。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Bring spools of silk from Moonsilk Hollow to Elder Sage Azhokar in Morogai Village.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41945, '摩洛盖村的菲娜·玛达尔想要月爪之脑来缓解头痛。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Fena Ma’dar in Moro’gai Village wants Lunarclaw brains to help with her headache.
