INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41972, '前往月蹄村，把托尔甘的信交给勇者野心。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Travel to Moonhoof Village and deliver Torgans Letter to Brave Wildheart.
