INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41998, '把一块原生德莱尼水晶原矿带给月蹄村的托比亚斯·浅墓。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Bring one Raw Draenethyst Formation to Thobias Shallowgrave in Moonhoof Village.
