INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (42012, '把托比亚斯的挎包交给月语海岸摩洛盖村的赫加拉。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Deliver Thobias’s Satchel to Heghala in Moro’gai Village, Moonwhisper Coast.
