INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (42017, '把奥汉兹之心带给月语海岸月蹄村的杜尔恩·灰图腾。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Bring Heart of Ohanzee to Duln Ashtotem in Moonhoof Village, Moonwhisper Coast.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (42019, '把一根雷象獠牙带给月语海岸月蹄村的乌尔夫·石图腾。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Bring an Elekk Tusk to Ulf Stonetotem in Moonhoof Village, Moonwhisper Coast.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (42020, '把长矛交给莫高雷血蹄村的胡尔夫纳·石图腾。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Deliver the spear to Hulfnar Stonetotem in Bloodhoof Village, Mulgore.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (42040, '为霜鬃洞穴中的拉尼克斯·裂弩取回卡兹甘石板。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Recover the Tablet of Kazgan for Ranix Crackbolt within Frostmane Hollow.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (42043, '为泰兰达斯太阳林地的护林者塞莱丝收集埃鲁纳里斯遗物。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Collect Elunaris Relics for Grovetender Sellais in the Grove of the Sun on Tyrandas.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (42044, '在月语海岸泰兰达斯的太阳林地与护林者塞莱丝交谈。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Speak to Grovetender Sellais in the Grove of the Sun on Tyrandas in Moonwhisper Coast.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (42045, '阅读受污染的符文，然后与寒脊山谷上方安威玛尔内的索林·暗窟交谈。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Read the Tainted Rune and speak to Thorinn Darkgrovel inside Anvilmar above Coldridge Valley.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (42048, '把雨角的挫败向月语湾月蹄村的长者月蹄汇报。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Report Rainhorn’s frustration to Elder Moonhoof in Moonhoof Village, Moonwhisper Cove.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (42050, '带着净化后的串珠回到月语海岸月蹄村的乌兹图克处。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Return to Uz’tuk with the cleansed Bundle of Beads in Moonhoof Village, Moonwhisper Coast.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (42054, '阅读神圣便笺，然后与纳拉其营地的努洛克·星行者交谈。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Read the Hallowed Note and speak to Nuhlok Starstrider in Camp Narache.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (42063, '把阿沙拉补给品交给月语海岸纳尔瓦利斯哨所的伊瑞亚·唤晨。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Deliver the Asharan Provisions to Irea Dawncaller in Narvalis Point on Moonwhisper Coast.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (42065, '把 40 颗坠落者首级带给月语海岸誓日营地的里斯·晨风。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Bring 40 Fallen One Heads to Rhys Dawnbreeze in Sunsworn Camp on Moonwhisper Coast.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (42067, '为月语海岸誓日营地的奥术师塞鲁隆取回陨星碎片。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Retrieve the Meteor Shard for Arcanist Cerulon in Sunsworn Camp on Moonwhisper Coast.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (42072, '回到月语海岸月蹄村去见年轻的月蹄。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Return to the younger Moonhoof in Moonhoof Village, Moonwhisper Coast.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (42073, '面见长者月蹄，然后在月语海岸月蹄村与他交谈。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Face the Elder Moonhoof and then speak to him in Moonhoof Village, Moonwhisper Coast.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (42089, '把 30 片潮刃之鳞带给纳尔瓦利斯哨所的哨兵指挥官银痕。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Bring 30 Tideblade Scales to Sentinel Commander Silverstreak at Narvalis Point.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (42092, '在星片摇篮杀死唤星者，然后回到月语海岸的扎拉扎尔处。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Slay Starcaller at the Starshard Cradle, then return to Zarazar on Moonwhisper Coast.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (42095, '在泰兰达斯岛的太阳林地与米拉伦修女交谈。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Speak with Sister Mirallun in the Grove of the Sun on the Isle of Tyrandas.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (7654, '要靴子图纸的话，我得先要 40 根瑟银锭。没错，40 根。要哭鼻子了？要不要给你块手帕？') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- For the boot plans, Ill be needin 40 thorium bars. Yep, 40. Are you gonna cry? Would you like a hanky?
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (8383, '把 3 枚奥特兰克山谷荣誉徽记带给战场外的联盟准将。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Bring 3 Alterac Valley Marks of Honor to an Alliance Brigadier General outside the battlegrounds.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (8384, '把 3 枚阿拉希盆地荣誉徽记带给战场外的联盟准将。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Bring 3 Arathi Basin Marks of Honor to an Alliance Brigadier General outside the battlegrounds.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (8386, '把 3 枚战歌峡谷荣誉徽记带给战场外的联盟准将。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Bring 3 Warsong Gulch Marks of Honor to an Alliance Brigadier General outside the battlegrounds.
