INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (8397, '把 3 枚阿拉希盆地荣誉徽记带给战场外的联盟准将。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Bring 3 Arathi Basin Marks of Honor to an Alliance Brigadier General outside the battlegrounds.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (8398, '把 3 枚阿拉希盆地荣誉徽记带给战场外的联盟准将。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Bring 3 Arathi Basin Marks of Honor to an Alliance Brigadier General outside the battlegrounds.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (8404, '把 3 枚战歌峡谷荣誉徽记带给战场外的联盟准将。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Bring 3 Warsong Gulch Marks of Honor to an Alliance Brigadier General outside the battlegrounds.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (8405, '把 3 枚战歌峡谷荣誉徽记带给战场外的联盟准将。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Bring 3 Warsong Gulch Marks of Honor to an Alliance Brigadier General outside the battlegrounds.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (8406, '把 3 枚战歌峡谷荣誉徽记带给战场外的联盟准将。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Bring 3 Warsong Gulch Marks of Honor to an Alliance Brigadier General outside the battlegrounds.
