INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (8408, '把 3 枚战歌峡谷荣誉徽记带给战场外的联盟准将。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Bring 3 Warsong Gulch Marks of Honor to an Alliance Brigadier General outside the battlegrounds.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41279, '在科尔桑废墟以东寻找赤褐色的巨人，把发现带回去见瑟格伦。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Search for the auburn giant east of the Ruins of Corthan and return to Thegren with your findings.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41281, '从玛拉顿取回一块兰斯利德的躯体碎片，带给荒芜之地科尔桑废墟附近的瑟格伦。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Recover a slab of Landslides body from Maraudon and bring it to Thegren near the Ruins of Corthan in the Badla
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41289, '在吉尔尼斯城寻找一本合适的书，带给荒芜之地卡加斯的加卡尔·苔须。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Search for a fitting book in Gilneas City and bring it to Jarkal Mossmeld in Kargath in the Badlands.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41292, '制作下列珠宝。向巧匠证明你的手艺之后，他会教你方法。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Craft the following jewelries. The Artificer will teach you how to after proving your skills to him.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41297, '从诅咒之地的德莱尼人手中夺回被翻乱的箱子，带回诅咒之地交给库米沙。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Recover the Rummaged Chest from the Draenei of the Blasted Lands and return it to Kumisha in the Blasted Lands
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41302, '回到铁炉堡秘法区的塔瓦斯德·基瑟尔处，付给他报酬。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Return to Talvash del Kissel.Kissel in the Mystic Ward of Ironforge and give him his payment.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41307, '收集特拉西斯丢失的货物，送到塔纳利斯热砂港他的雇主手中。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Collect the missing cargo of Traxis and deliver it to his contractor in Steamwheedle Port in Tanaris.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41322, '艾萨拉的阿克扎多尔需要西边熊怪的草药和东边龙虾人的肉。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Akh Zador in Azshara requires herbs from the furbolgs to the west and flesh of the makrura to the east.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41325, '面对在黑暗之门作祟的东西，然后回到俯瞰诅咒之地的卡斯塔尔处。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Face whatever is meddling at the Dark Portal and return to Kastal overlooking the Blasted Lands.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41339, '调查暗谷隘口附近的异常，然后向诺达纳尔的大德鲁伊梦风汇报。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Investigate the disturbances near Darkhollow Pass and report to Arch Druid Dreamwind at Nordanaar.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41344, '从格里兹基尔手中夺回大得滑稽的蜡烛，回到卡拉赞上层交给大胡须。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Recover the Comically Large Candle from Grizikil and return to Big Whiskers in Upper Karazhan.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41347, '伯爵夫人蒂莉亚·厄尔威克在寻找她被偷的项链。她最后一次见到它是在暴风城的宅邸里。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Countess Tillia Earlwake seeks her stolen necklace. The last time she saw it was in her estate in Stormwind Ci
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41351, '找到拉祖夫·伊瓦尔迪，从他那夺回蒂莉亚的项链，在卡拉赞下层大厅的歌剧院交还给她。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Find Razuv Ivaldi and take Tillias necklace from him. Return it to her in the opera of the Lower Karazhan Hall
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41362, '把所需的材料带给洛克索斯·黑商。他在黑石深渊的黑铁酒吧等候。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Bring Lokthos Darkbargainer the needed materials. He waits in the Grim Guzzler in the Blackrock Depths.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41363, '奥伯丁的桑德里斯·织风需要哀嚎洞穴中异常蔓生物的样本。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Thundris Windweaver in Auberdine needs samples of the Unnatural Overgrowths in the Wailing Caverns.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41367, '在哀嚎洞穴杀死赞达拉·风蹄，把她的首级带回贫瘠之地交给纳尔帕克。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Slay Zandara Windhoof within Wailing Caverns, and bring her head back to Nalpak in the Barrens.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41378, '为范达尔·鹿盔收集狼人之血。他需要来自卡拉赞、吉尔尼斯城和影牙城堡的血样。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Gather worgen blood for Fandral Staghelm. He requires blood samples from Karazhan, Gilneas City and Shadowfang
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41381, '为玛加萨·野性图腾收集狼人之血。她需要来自卡拉赞、吉尔尼斯城和影牙城堡的血样。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Gather worgen blood for Magatha Grimtotem. She requires blood samples from Karazhan, Gilneas City and Shadowfa
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41394, '把 6 块永恒梦境石碎片、20 卷月布和一份恐惧魔王之魂带给大德鲁伊梦风。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Bring 6 Eternal Dreamstone Shards, 20 Mooncloth and Soul of a Dreadlord to Arch Druid Dreamwind.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41396, '协助月光林地的守护者雷姆洛斯，把制作沉眠梦幕所需的材料带给他。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Assist Keeper Remulos in Moonglade by bringing him the needed materials to craft a slumbering dreamveil.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41397, '找到绿龙维瑟库斯的遗骸，与他沟通，然后回到月光林地的守护者雷姆洛斯处。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Locate the remains of the green dragon Vithekus, commune with him and return to Keeper Remulos in Moonglade.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41523, '取得阿曼尼投掷斧，献给贫瘠之地弗雷岛的马赛厄斯·明心。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Acquire the Throwing Axes of the Amani and offer it to Mathias Brightheart on Fray Island in the Barrens.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41636, '从北部山中的盗贼手里夺回箱子，带到安伯郡教堂交给银白修女。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Retrieve the crate from the thieves in the northern mountains and bring it to Sister Argent at the Ambershire 
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41638, '找到格雷厄姆修士母亲的骨灰瓮，带回北风安伯郡教堂交给他。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Find the urn of Brother Grahams mother and return it to him at the Ambershire Church in Northwind.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41645, '搜查舍伍德采石场。把任何有用的发现带回安伯郡交给特工霍桑。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Search Sherwood Quarry. Return to Operative Hawthorne in Ambershire with anything useful you find.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41648, '为北风西北女巫集舍中的北风女巫取得所需材料。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Acquire the needed material for the Witch of Northwind in her coven in northwestern Northwind.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41667, '去阿拉萨拉斯向查杜斯·负日打听一副附魔马蹄铁，然后回到指挥官莱德处。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Seek Chaddus Suncarrier in AlahThalas about a pair of enchanted horse shoes and return to Commander Leder.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41668, '收集一包琥珀釉甜甜圈、一捆苹果和英格薇尔德的派，回到雕像旁的她那里。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Gather a pack of Amberglaze Donuts, Bundle of Apples and Ingvilds Pie and return to her by the statue.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41671, '在旧修道院杀死哀嚎修女，取回《北风亡灵录》，交给园丁克莱夫。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Kill The Wailing Nun in the old Abbey and retrieve the Northwind Necrology, return it to Groundskeeper Clive.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41674, '在北风酒庄外围田地杀死 20 名黑石入侵者。完成后回到老克劳福德处。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Slay 20 Blackrock Invaders in the outer fields of Northwind Winery. Return to Old Man Crawford when done.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41676, '为德里斯科尔上校杀死霸主斯罗克、奥祖克·厄刺和舒尼·钢牙，然后回去复命。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Kill Overlord Throkk, Ozuk Doomspike and Shuni Steeltooth for Colonel Driscol and return to him.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41677, '破坏 15 桶黑铁火药，然后回到北风肥南瓜酒馆的德里斯科尔上校处。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Sabotage fifteen Dark Iron Gunpowder Kegs and return to Colonel Driscol at the Plump Pumpkin in Northwind.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41683, '为杜尔·狼嗥杀死霸主斯罗克、奥祖克·厄刺和舒尼·钢牙，然后回去复命。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Kill Overlord Throkk, Ozuk Doomspike and Shuni Steeltooth for Dul Wolfsnarl and return to him.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41684, '找到北风女巫描述的地点，之后回到安伯郡向特工霍桑汇报。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Find the location described by the Witch of Northwind and report to Operative Hawthorne in Ambershire afterwar
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41687, '击退围攻舍伍德采石场的黑铁矮人，然后回到北风比武场的舍伍德公爵处。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Repel the Dark Iron siege on Sherwood Quarry and return to Duke Sherwood at the Jousting Ground in Northwind.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41697, '为军情七处哨站的尼普西·刺距，清除巴洛西侧洞穴中的恶魔。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Clear out the demons in the cave on the western side of Balor for Nippsy Spickerspan at the SI:7 Outpost.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41701, '巴洛北部岛上的佩妮·素钢要你清剿当地的龙虾人和鱼人。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Penny Plainsteel on the northern island of Balor wants you to eradicate the local makrura and murlocs.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41705, '搜查巴洛战场上方洞穴中的遗物，把它带回巴洛教堂里的那位女子手中。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Search the cave atop the battlefield on Balor and return with a memento to the woman inside the Balor church.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41706, '为岛上西侧崖边的梅森德拉·枭爪，从巴洛的野生动物身上收集污秽精华。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- Collect Foul Essences from Balors wildlife for Methendra Owltalon on the western cliff of the island.
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41708, '为了补充毒药储备，巴洛军情七处哨站的金里尔需要雾皮蜘蛛的毒囊。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- To bolster their poison supplies, Kinrial in the SI:7 Outpost on Balor needs venom sacs of the Mistbark spider
